INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5080821, 741314, 80904, '<td valign="top">I dont know, It looks like a bed to me. No vote. Nice picture though</td>', 'I dont know, It looks like a bed to me. No vote. Nice picture though', '2008-11-24 00:02:50.000000', NULL, 1),
(5080826, 741350, 80904, '<td valign="top">I would expect this one to win top three. This tells a great story</td>', 'I would expect this one to win top three. This tells a great story', '2008-11-24 00:05:34.000000', NULL, 1),
(5080832, 741350, 29906, '<td valign="top">Great shot. You get a 10 from me.</td>', 'Great shot. You get a 10 from me.', '2008-11-24 00:09:11.000000', NULL, 1),
(5080837, 741376, 66616, '<td valign="top">excellent</td>', 'excellent', '2008-11-24 00:10:48.000000', NULL, 1),
(5080840, 740977, 33552, '<td valign="top">"It''s the circles isn''t it?" -The Big Kahuna, Psycho Beach Party<br/> <br/>Great pattern, excellent colors. Whats going on with the building in the BG?</td>', '"It''s the circles isn''t it?" -The Big Kahuna, Psycho Beach Party Great pattern, excellent colors. Whats going on with the building in the BG?', '2008-11-24 00:11:15.000000', NULL, 1),
(5080843, 741447, 33552, '<td valign="top">The perspective is making me dizzy! Careful on the saturation there.</td>', 'The perspective is making me dizzy! Careful on the saturation there.', '2008-11-24 00:12:43.000000', NULL, 1),
(5080844, 741448, 33552, '<td valign="top">Nice. Good tonality throughout. Pleasing pattern.</td>', 'Nice. Good tonality throughout. Pleasing pattern.', '2008-11-24 00:13:43.000000', NULL, 1),
(5080849, 741489, 33672, '<td valign="top">Very well done.</td>', 'Very well done.', '2008-11-24 00:14:43.000000', NULL, 1),
(5080850, 741434, 33552, '<td valign="top">A bit busy with the leaves. Good framing, but it still feels a bit cluttered.</td>', 'A bit busy with the leaves. Good framing, but it still feels a bit cluttered.', '2008-11-24 00:15:00.000000', NULL, 1),
(5080852, 741057, 33672, '<td valign="top">Nice leading lines.</td>', 'Nice leading lines.', '2008-11-24 00:16:06.000000', NULL, 1),
(5080853, 741248, 33672, '<td valign="top">Nice angle shot!</td>', 'Nice angle shot!', '2008-11-24 00:17:26.000000', NULL, 1),
(5080854, 741355, 33552, '<td valign="top">Well done both technically and artisticlly. Still, a bit heavy handed. Can''t blame ya'' though, given DPC''s standards.</td>', 'Well done both technically and artisticlly. Still, a bit heavy handed. Can''t blame ya'' though, given DPC''s standards.', '2008-11-24 00:17:30.000000', NULL, 1),
(5080856, 741341, 33672, '<td valign="top">It could sit in a place like that for hours. Great capture.</td>', 'It could sit in a place like that for hours. Great capture.', '2008-11-24 00:18:02.000000', NULL, 1),
(5080859, 741234, 33552, '<td valign="top">I have a really hard time with exploitation candids. They should at least carry an obvious social commentary. The colors and exposure are a bit flat. Still, the framing is decent.</td>', 'I have a really hard time with exploitation candids. They should at least carry an obvious social commentary. The colors and exposure are a bit flat. Still, the framing is decent.', '2008-11-24 00:20:03.000000', NULL, 1),
(5080860, 741500, 33672, '<td valign="top">Nice idea. B&amp;W works well.</td>', 'Nice idea. B&W works well.', '2008-11-24 00:20:56.000000', NULL, 1),
(5080864, 741449, 33552, '<td valign="top">Excellent framing and composition. I might have gone monochrome here, but I do think this needs a bit more contrast, while at the same time a toning down of the hair highlight. A tall order, huh?</td>', 'Excellent framing and composition. I might have gone monochrome here, but I do think this needs a bit more contrast, while at the same time a toning down of the hair highlight. A tall order, huh?', '2008-11-24 00:22:36.000000', NULL, 1),
(5080865, 741402, 33672, '<td valign="top">Nice tones and POV. Works well in B&amp;W.</td>', 'Nice tones and POV. Works well in B&W.', '2008-11-24 00:23:06.000000', NULL, 1),
(5080868, 741285, 33552, '<td valign="top">As exploitation candids go, this certainly has a worthy point of interest. Not sure I care for the square crop and super high contrast.</td>', 'As exploitation candids go, this certainly has a worthy point of interest. Not sure I care for the square crop and super high contrast.', '2008-11-24 00:24:22.000000', NULL, 1),
(5080871, 741039, 100761, '<td valign="top">I love the blurred movement of the rest of the city, while the people on the bench are in their own world.</td>', 'I love the blurred movement of the rest of the city, while the people on the bench are in their own world.', '2008-11-24 00:26:13.000000', NULL, 1),
(5080873, 741341, 33552, '<td valign="top">The colors are a bit off, but this is a great shot! The same spot in early morning or late evening would be something!</td>', 'The colors are a bit off, but this is a great shot! The same spot in early morning or late evening would be something!', '2008-11-24 00:27:02.000000', NULL, 1),
(5080877, 741310, 100761, '<td valign="top">The soft focus really suits this photo.</td>', 'The soft focus really suits this photo.', '2008-11-24 00:27:43.000000', NULL, 1),
(5080878, 741309, 100761, '<td valign="top">awwwwww.</td>', 'awwwwww.', '2008-11-24 00:27:57.000000', NULL, 1),
(5080881, 741435, 100761, '<td valign="top">Looks like a great place to enjoy the view!</td>', 'Looks like a great place to enjoy the view!', '2008-11-24 00:28:44.000000', NULL, 1),
(5080884, 741376, 33068, '<td valign="top">Outstanding composition,tones,and emotion.  I''m in love with that tree.  10</td>', 'Outstanding composition,tones,and emotion.  I''m in love with that tree.  10', '2008-11-24 00:29:16.000000', NULL, 1),
(5080885, 741459, 33552, '<td valign="top">Ohhhhh, I like repetition! Nice pattern, try completely desaturating the blue channel and see what you think. I love the wide format.</td>', 'Ohhhhh, I like repetition! Nice pattern, try completely desaturating the blue channel and see what you think. I love the wide format.', '2008-11-24 00:29:19.000000', NULL, 1),
(5080887, 741318, 100761, '<td valign="top">feels so loneley</td>', 'feels so loneley', '2008-11-24 00:29:30.000000', NULL, 1),
(5080888, 741430, 33552, '<td valign="top">A little less off the upper left might focus the attention better. Nice concept.</td>', 'A little less off the upper left might focus the attention better. Nice concept.', '2008-11-24 00:30:26.000000', NULL, 1),
(5080890, 741483, 33068, '<td valign="top">This is unique.  I really like the idea and post processing.  I think I would have changed the crop slightly so the doll was not dead center though.</td>', 'This is unique.  I really like the idea and post processing.  I think I would have changed the crop slightly so the doll was not dead center though.', '2008-11-24 00:30:56.000000', NULL, 1),
(5080892, 741310, 33552, '<td valign="top">Great concept. A bit heavy handed on the processing, but it doesn''t go too too far.</td>', 'Great concept. A bit heavy handed on the processing, but it doesn''t go too too far.', '2008-11-24 00:31:57.000000', NULL, 1),
(5080894, 741489, 33068, '<td valign="top">Wow!  This is fantastic.  I love everything about this... from the motion blur, to the pov, to the post processing.  I''ve always wanted to shoot something like this but never have.  VERY COOL! 10</td>', 'Wow!  This is fantastic.  I love everything about this... from the motion blur, to the pov, to the post processing.  I''ve always wanted to shoot something like this but never have.  VERY COOL! 10', '2008-11-24 00:32:33.000000', NULL, 1),
(5080895, 741453, 33068, '<td valign="top">Nice abstract.</td>', 'Nice abstract.', '2008-11-24 00:32:43.000000', NULL, 1),
(5080897, 741285, 33068, '<td valign="top">Doesn''t scream bench but I like the expression you''ve captured.</td>', 'Doesn''t scream bench but I like the expression you''ve captured.', '2008-11-24 00:33:03.000000', NULL, 1),
(5080898, 741332, 33552, '<td valign="top">Shoehorn, but still a great shot. I have to say that the gull makes this work.</td>', 'Shoehorn, but still a great shot. I have to say that the gull makes this work.', '2008-11-24 00:33:13.000000', NULL, 1),
(5080900, 741419, 33552, '<td valign="top">With exploitation candids, I hope to see something present in the initial capture that makes the shot worthy. This looks to be all processing. The processing is certainly well done, but the composition seems lacking.</td>', 'With exploitation candids, I hope to see something present in the initial capture that makes the shot worthy. This looks to be all processing. The processing is certainly well done, but the composition seems lacking.', '2008-11-24 00:35:22.000000', NULL, 1),
(5080909, 741259, 30861, '<td valign="top">I see chairs actually, not a bench or benches... Very unusual processing :-</td>', 'I see chairs actually, not a bench or benches... Very unusual processing :-', '2008-11-24 00:39:15.000000', NULL, 1),
(5080914, 741277, 30861, '<td valign="top">Heck, I''ve just had two rides in one of those this month... Works for me.</td>', 'Heck, I''ve just had two rides in one of those this month... Works for me.', '2008-11-24 00:41:29.000000', NULL, 1),
(5080915, 741230, 30861, '<td valign="top">id</td>', 'id', '2008-11-24 00:41:33.000000', NULL, 1),
(5080918, 740079, 33552, '<td valign="top">Interesting contemporary depiction of the Moirai. A bold composition that would benefit from a bit of perspective correction. Good monochrome conversion.</td>', 'Interesting contemporary depiction of the Moirai. A bold composition that would benefit from a bit of perspective correction. Good monochrome conversion.', '2008-11-24 00:42:57.000000', NULL, 1),
(5080919, 741230, 33552, '<td valign="top">Wow! Trippy! I don''t know what else to say.</td>', 'Wow! Trippy! I don''t know what else to say.', '2008-11-24 00:44:09.000000', NULL, 1),
(5080926, 741402, 33552, '<td valign="top">The overexposed reflection hurts this otherwise remarkable shot. Nice job pushing the contrast.</td>', 'The overexposed reflection hurts this otherwise remarkable shot. Nice job pushing the contrast.', '2008-11-24 00:54:37.000000', NULL, 1),
(5080928, 741361, 33552, '<td valign="top">There is something really disturbing about this shot. A bit too much contrast perhaps.</td>', 'There is something really disturbing about this shot. A bit too much contrast perhaps.', '2008-11-24 00:57:43.000000', NULL, 1),
(5080930, 741452, 33552, '<td valign="top">Trippy selective desat. Nice composition.</td>', 'Trippy selective desat. Nice composition.', '2008-11-24 00:58:20.000000', NULL, 1),
(5080939, 741039, 33552, '<td valign="top">In many ways this is a nice night shot, but I keep looking at the pure black shadows for more information. The composition also seems a bit loose.</td>', 'In many ways this is a nice night shot, but I keep looking at the pure black shadows for more information. The composition also seems a bit loose.', '2008-11-24 01:00:48.000000', NULL, 1),
(5080941, 741033, 33552, '<td valign="top">Whoa! Photomatix? A bit over processed for my tastes.</td>', 'Whoa! Photomatix? A bit over processed for my tastes.', '2008-11-24 01:01:57.000000', NULL, 1),
(5080942, 741154, 33552, '<td valign="top">Be careful with the tone mapping! It can go too far. Still, nice composition and overall color scheme.</td>', 'Be careful with the tone mapping! It can go too far. Still, nice composition and overall color scheme.', '2008-11-24 01:03:42.000000', NULL, 1),
(5080945, 741446, 22301, '<td valign="top">thats awesome, I wonder how you did it! well done.</td>', 'thats awesome, I wonder how you did it! well done.', '2008-11-24 01:06:12.000000', NULL, 1),
(5080946, 741375, 33552, '<td valign="top">Technically excellent, but I''m afraid that to anyone who dosen''t know her, this won''t say much about her.  Tell us who Becky <i>is</i>.</td>', 'Technically excellent, but I''m afraid that to anyone who dosen''t know her, this won''t say much about her.  Tell us who Becky is.', '2008-11-24 01:06:42.000000', NULL, 1),
(5080947, 741446, 28322, '<td valign="top">Wowww, I think we have a winner, wonderful by all meannnnnnnnn, can''t find any thing to critique .. 10 from me.</td>', 'Wowww, I think we have a winner, wonderful by all meannnnnnnnn, can''t find any thing to critique .. 10 from me.', '2008-11-24 01:06:50.000000', NULL, 1),
(5080949, 741369, 37252, '<td valign="top">and that my friend is worth a 10 :)<br/> <br/>excellent shot - composition is right on and the sun perfect!</td>', 'and that my friend is worth a 10 :) excellent shot - composition is right on and the sun perfect!', '2008-11-24 01:08:11.000000', NULL, 1),
(5080951, 741498, 33552, '<td valign="top">It''s a bench! I love the colors and the comp, but it''s still just a bench. Still, better than average.</td>', 'It''s a bench! I love the colors and the comp, but it''s still just a bench. Still, better than average.', '2008-11-24 01:08:35.000000', NULL, 1),
(5080953, 741444, 33552, '<td valign="top">A bit heavy on the contrast, but it works in this case. Nice mood shot.</td>', 'A bit heavy on the contrast, but it works in this case. Nice mood shot.', '2008-11-24 01:10:01.000000', NULL, 1),
(5080957, 741314, 22301, '<td valign="top">I hope you win.</td>', 'I hope you win.', '2008-11-24 01:11:45.000000', NULL, 1),
(5080958, 741314, 28322, '<td valign="top">Wonderful, 10 from me.</td>', 'Wonderful, 10 from me.', '2008-11-24 01:12:57.000000', NULL, 1),
(5080959, 741083, 28322, '<td valign="top">Wonderful atmosphere, 9 from me.<br/>Edited .. after going through the challenge, this deserve a 10 :)</td>', 'Wonderful atmosphere, 9 from me.Edited .. after going through the challenge, this deserve a 10 :)', '2008-11-24 01:14:14.000000', NULL, 1),
(5080960, 741376, 28322, '<td valign="top">Wonderful composition, I love how you included the tree in the capture, 9 from me.<br/>Edited. <br/>After going through the challenge, this deserve a 10 :)</td>', 'Wonderful composition, I love how you included the tree in the capture, 9 from me.Edited. After going through the challenge, this deserve a 10 :)', '2008-11-24 01:14:32.000000', NULL, 1),
(5080964, 741487, 33552, '<td valign="top">I see what you''re going for, but it took me about three minutes, literally, to notice the ring. My attention is just pulled to the upper left. An off camera flash to the left of the camera and a bit above, as well as a tighter crop, might have helped a bit.</td>', 'I see what you''re going for, but it took me about three minutes, literally, to notice the ring. My attention is just pulled to the upper left. An off camera flash to the left of the camera and a bit above, as well as a tighter crop, might have helped a bit.', '2008-11-24 01:15:19.000000', NULL, 1),
(5080965, 741083, 37252, '<td valign="top">Beautiful piece of art right here. 10</td>', 'Beautiful piece of art right here. 10', '2008-11-24 01:16:51.000000', NULL, 1),
(5080967, 741337, 33552, '<td valign="top">The super high contrast certainly helps bring out the snow, but detail is lost in the background trees. The forked footpath adds interest, but it''s just too overprocessed. Still, it creates a nice mood.</td>', 'The super high contrast certainly helps bring out the snow, but detail is lost in the background trees. The forked footpath adds interest, but it''s just too overprocessed. Still, it creates a nice mood.', '2008-11-24 01:17:23.000000', NULL, 1),
(5080973, 741050, 33552, '<td valign="top">A bit high on the contrast, but I can still tell it''s a beautiful scene. I like the duck''s wake, It leads the eye into the frame.</td>', 'A bit high on the contrast, but I can still tell it''s a beautiful scene. I like the duck''s wake, It leads the eye into the frame.', '2008-11-24 01:27:31.000000', NULL, 1),
(5080974, 741317, 100844, '<td valign="top">great texture and color</td>', 'great texture and color', '2008-11-24 01:29:43.000000', NULL, 1),
(5080976, 741435, 33552, '<td valign="top">Bump the contrast a bit further. It''s a great scene, but it lacks ... "pop". I''d also loose a bit off the bottom to square it up a bit. This same scene about 30-60 minutes later in the evening/earlier in the morning might scream ribbon.</td>', 'Bump the contrast a bit further. It''s a great scene, but it lacks ... "pop". I''d also loose a bit off the bottom to square it up a bit. This same scene about 30-60 minutes later in the evening/earlier in the morning might scream ribbon.', '2008-11-24 01:31:34.000000', NULL, 1),
(5080981, 741334, 33552, '<td valign="top">Dangerously close to exploitation, but the composition is pleasing, and the message not entirely negative. There is hope in the symbolism of a lone dove/pigeon. Technically well done, if a bit under exposed.</td>', 'Dangerously close to exploitation, but the composition is pleasing, and the message not entirely negative. There is hope in the symbolism of a lone dove/pigeon. Technically well done, if a bit under exposed.', '2008-11-24 01:35:52.000000', NULL, 1),
(5080988, 740873, 30861, '<td valign="top">I don''t understand why you wouldn''t change your position a bit to the left so this bench was fully defined. For me t''s a crippling defect in an otherwise truly promising image...</td>', 'I don''t understand why you wouldn''t change your position a bit to the left so this bench was fully defined. For me t''s a crippling defect in an otherwise truly promising image...', '2008-11-24 01:43:58.000000', NULL, 1),
(5080989, 741337, 34938, '<td valign="top">love the tones and composition in this...excellent 9</td>', 'love the tones and composition in this...excellent 9', '2008-11-24 01:46:20.000000', NULL, 1),
(5080990, 740557, 34938, '<td valign="top">should do well, excellent shot 8</td>', 'should do well, excellent shot 8', '2008-11-24 01:46:40.000000', NULL, 1),
(5080991, 741448, 34938, '<td valign="top">nice b and w conversion 8</td>', 'nice b and w conversion 8', '2008-11-24 01:47:40.000000', NULL, 1),
(5080992, 741057, 30861, '<td valign="top">There''s an unassuming richness to this utterly guileless image that I find very appealing.</td>', 'There''s an unassuming richness to this utterly guileless image that I find very appealing.', '2008-11-24 01:47:59.000000', NULL, 1),
(5080993, 741050, 63812, '<td valign="top">really beautiful. sure we will see it on first page.</td>', 'really beautiful. sure we will see it on first page.', '2008-11-24 01:48:04.000000', NULL, 1),
(5080994, 741438, 34938, '<td valign="top">I know you might get criticesed for it, but I love the edit...has given it a surreal feel 8</td>', 'I know you might get criticesed for it, but I love the edit...has given it a surreal feel 8', '2008-11-24 01:48:20.000000', NULL, 1),
(5080995, 741318, 64670, '<td valign="top">Beautiful - Lovely, WONDERFUL!</td>', 'Beautiful - Lovely, WONDERFUL!', '2008-11-24 01:48:54.000000', NULL, 1),
(5081000, 741376, 34938, '<td valign="top">excellent atmospheric image, conveys the emotion 8</td>', 'excellent atmospheric image, conveys the emotion 8', '2008-11-24 01:50:34.000000', NULL, 1),
(5081001, 741442, 30861, '<td valign="top">a very serene image, nicely crafted in PP, marred, IMO, by the careless juxtaposition of the bench''s leading edge precisely over the shoreline. Lowering the POV perhaps six inches would have resolved this issue.</td>', 'a very serene image, nicely crafted in PP, marred, IMO, by the careless juxtaposition of the bench''s leading edge precisely over the shoreline. Lowering the POV perhaps six inches would have resolved this issue.', '2008-11-24 01:51:05.000000', NULL, 1),
(5081002, 741378, 30861, '<td valign="top">nc</td>', 'nc', '2008-11-24 01:51:29.000000', NULL, 1),
(5081003, 741416, 34938, '<td valign="top">dramatic, well done</td>', 'dramatic, well done', '2008-11-24 01:51:58.000000', NULL, 1),
(5081006, 741007, 34938, '<td valign="top">good luck with this...excellent exposure 8</td>', 'good luck with this...excellent exposure 8', '2008-11-24 01:53:02.000000', NULL, 1),
(5081008, 741446, 30861, '<td valign="top">Good Grief... I can''t wait to hear the story behind this one.</td>', 'Good Grief... I can''t wait to hear the story behind this one.', '2008-11-24 01:53:40.000000', NULL, 1),
(5081010, 741487, 63812, '<td valign="top">nice picture!</td>', 'nice picture!', '2008-11-24 01:54:27.000000', NULL, 1),
(5081011, 741417, 34938, '<td valign="top">great find! 8</td>', 'great find! 8', '2008-11-24 01:55:41.000000', NULL, 1),
(5081015, 741446, 34938, '<td valign="top">the image is clever, but I can''t see how you achieved this without breaking the rules of the dpchallenge site???? will give the benefit of the doubt of course</td>', 'the image is clever, but I can''t see how you achieved this without breaking the rules of the dpchallenge site???? will give the benefit of the doubt of course', '2008-11-24 01:58:51.000000', NULL, 1),
(5081016, 739847, 33552, '<td valign="top">Technically exellent! The compositon really works, but I have to admit that I find these shots really creepy.</td>', 'Technically exellent! The compositon really works, but I have to admit that I find these shots really creepy.', '2008-11-24 02:07:23.000000', NULL, 1),
(5081017, 741493, 33552, '<td valign="top">Ok. High contrast. Visually interesting, but the question remains... why? What does this say? I''m afraid I''m confused.</td>', 'Ok. High contrast. Visually interesting, but the question remains... why? What does this say? I''m afraid I''m confused.', '2008-11-24 02:09:04.000000', NULL, 1),
(5081021, 741266, 33552, '<td valign="top">Can''t tell if the lake/ocean is frozen or if it''s just contrast pushed in post. Still, it does convey a mood of stillness or even lonliness. I''d like to see the framing pushed a bit to the right. Centered compositions often generate a clinical appearance that tends to detract from the mood of the image.</td>', 'Can''t tell if the lake/ocean is frozen or if it''s just contrast pushed in post. Still, it does convey a mood of stillness or even lonliness. I''d like to see the framing pushed a bit to the right. Centered compositions often generate a clinical appearance that tends to detract from the mood of the image.', '2008-11-24 02:13:46.000000', NULL, 1),
(5081022, 741376, 63812, '<td valign="top">lovely picture</td>', 'lovely picture', '2008-11-24 02:15:44.000000', NULL, 1),
(5081023, 741200, 33552, '<td valign="top">I love the colors and pattrn here, but the overall image appears a bit flat. Pulling up the black point slider in a levels adjustment may add a bit more contrast or "pop".</td>', 'I love the colors and pattrn here, but the overall image appears a bit flat. Pulling up the black point slider in a levels adjustment may add a bit more contrast or "pop".', '2008-11-24 02:16:04.000000', NULL, 1),
(5081028, 741356, 33552, '<td valign="top">Great timing, the contrast certainly adds drama. OTOH, the contrast is a bit harsh. I rarely advocate for soft focus and vignettes, but a tender moment might work better with that style. OTOOH, a rebellion against convention adds an edge to an otherwise somewhat cliche shot. As you can probably see, I''m a bit conflicted here.</td>', 'Great timing, the contrast certainly adds drama. OTOH, the contrast is a bit harsh. I rarely advocate for soft focus and vignettes, but a tender moment might work better with that style. OTOOH, a rebellion against convention adds an edge to an otherwise somewhat cliche shot. As you can probably see, I''m a bit conflicted here.', '2008-11-24 02:30:31.000000', NULL, 1),
(5081031, 741499, 33552, '<td valign="top">I''m not really sure if there was a particular message you were going for, but this does come off as a bit exploitative and opportunistic. If there is a message other than "hey, look what i found", I don''t see it. Sorry.</td>', 'I''m not really sure if there was a particular message you were going for, but this does come off as a bit exploitative and opportunistic. If there is a message other than "hey, look what i found", I don''t see it. Sorry.', '2008-11-24 02:33:30.000000', NULL, 1),
(5081034, 741317, 33552, '<td valign="top">Very nice, the high contrast actually works here! Beautiful landscape and nice timing.</td>', 'Very nice, the high contrast actually works here! Beautiful landscape and nice timing.', '2008-11-24 02:36:03.000000', NULL, 1),
(5081041, 741161, 33552, '<td valign="top">A touching candid. Could probably be cropped in a bit.</td>', 'A touching candid. Could probably be cropped in a bit.', '2008-11-24 02:51:57.000000', NULL, 1),
(5081046, 741110, 33552, '<td valign="top">The low perspective creates a sense of inferiority in the viewer. This may be intentional here, but the tilted perspective and the abrupt crop/framing create a disturbing image. My own bias certainly comes into play here, but the overall darkness alongside the afore mentioned elements does create an ominous mood.</td>', 'The low perspective creates a sense of inferiority in the viewer. This may be intentional here, but the tilted perspective and the abrupt crop/framing create a disturbing image. My own bias certainly comes into play here, but the overall darkness alongside the afore mentioned elements does create an ominous mood.', '2008-11-24 02:57:29.000000', NULL, 1),
(5081047, 741218, 33552, '<td valign="top">Among the overly-contrasty and false color images here, this one does stand out. I love the concept and composition. The contrast and colors work to enhance an otherworldly appearance to this image.</td>', 'Among the overly-contrasty and false color images here, this one does stand out. I love the concept and composition. The contrast and colors work to enhance an otherworldly appearance to this image.', '2008-11-24 03:00:58.000000', NULL, 1),
(5081051, 739834, 33552, '<td valign="top">There is a point where a tilted perspective adds action to an otherwise static perspective. Then there is a point where the impression is more one of having several dozen helium baloons tied to ones ankle. I''m afraid this is closer to the latter.</td>', 'There is a point where a tilted perspective adds action to an otherwise static perspective. Then there is a point where the impression is more one of having several dozen helium baloons tied to ones ankle. I''m afraid this is closer to the latter.', '2008-11-24 03:05:35.000000', NULL, 1),
