(5086669, 741433, 51597, '<td valign="top">Well seen and taken!!! .. Sits just right in your shot and the lines of the bridge take one the distance.. <br/> <br/>I think this is one of the best in the challenge..</td>', 'Well seen and taken!!! .. Sits just right in your shot and the lines of the bridge take one the distance..  I think this is one of the best in the challenge..', '2008-11-26 21:35:39.000000', NULL, 1),
(5086670, 740483, 51597, '<td valign="top">Yet another great shot!!</td>', 'Yet another great shot!!', '2008-11-26 21:36:34.000000', NULL, 1),
