(5086680, 741440, 51597, '<td valign="top">Reminds me of home!!</td>', 'Reminds me of home!!', '2008-11-26 21:42:16.000000', NULL, 1),
(5086686, 741161, 51597, '<td valign="top">Am lost in this by balance / proportionately off somehow.. other wise love subjects &amp; setting..</td>', 'Am lost in this by balance / proportionately off somehow.. other wise love subjects & setting..', '2008-11-26 21:46:03.000000', NULL, 1),
