(5086804, 741446, 37252, '<td valign="top">This one makes me laugh. I like it alot. Oddly the dog''s face, what can be seen of it, looks plastic. I''d love to know how you pulled this off as I cannot imagine how you got the sparks</td>', 'This one makes me laugh. I like it alot. Oddly the dog''s face, what can be seen of it, looks plastic. I''d love to know how you pulled this off as I cannot imagine how you got the sparks', '2008-11-27 00:38:04.000000', NULL, 1),
(5086806, 741033, 37252, '<td valign="top">I love the composition - it''s strong ans symetrical</td>', 'I love the composition - it''s strong ans symetrical', '2008-11-27 00:38:57.000000', NULL, 1),
(5086807, 740557, 37252, '<td valign="top">Stunning colors in the sky - great job</td>', 'Stunning colors in the sky - great job', '2008-11-27 00:39:17.000000', NULL, 1),
(5086808, 741350, 37252, '<td valign="top">very nice pp</td>', 'very nice pp', '2008-11-27 00:46:05.000000', NULL, 1),
(5086809, 741228, 37252, '<td valign="top">Are those rays real? Love the shape of the bench.</td>', 'Are those rays real? Love the shape of the bench.', '2008-11-27 00:47:05.000000', NULL, 1),
(5086810, 741154, 37252, '<td valign="top">Interesting - the image itself says "calm, peaceful, quite"  The technical image looks to have a bit of noise to it.</td>', 'Interesting - the image itself says "calm, peaceful, quite"  The technical image looks to have a bit of noise to it.', '2008-11-27 00:48:48.000000', NULL, 1),
(5086813, 740841, 37252, '<td valign="top">Well composed. The placement of the person and dog in relation to your angle on the bench is perfect.</td>', 'Well composed. The placement of the person and dog in relation to your angle on the bench is perfect.', '2008-11-27 00:50:10.000000', NULL, 1),
(5086814, 740782, 37252, '<td valign="top">Perfect title! I love the lone leaf sitting on the bench. Excellent bokeh too.</td>', 'Perfect title! I love the lone leaf sitting on the bench. Excellent bokeh too.', '2008-11-27 00:50:53.000000', NULL, 1),
(5086817, 741419, 37252, '<td valign="top">A sad reality</td>', 'A sad reality', '2008-11-27 00:55:17.000000', NULL, 1),
(5086818, 741426, 37252, '<td valign="top">I see a lot of noise in this image, but I think it works WITH the image and not against it. The textures seem to jump out more from it. I also get the actual feel of the cold crisp air. 8</td>', 'I see a lot of noise in this image, but I think it works WITH the image and not against it. The textures seem to jump out more from it. I also get the actual feel of the cold crisp air. 8', '2008-11-27 00:56:46.000000', NULL, 1),
(5086820, 741483, 37252, '<td valign="top">Selective desat is perfect for this image. Nice shot.</td>', 'Selective desat is perfect for this image. Nice shot.', '2008-11-27 00:59:52.000000', NULL, 1),
(5086822, 741448, 37252, '<td valign="top">B/W is a great choice for this. The curves are a welcome difference from the square or boxy feeling of most entries in this challenge.</td>', 'B/W is a great choice for this. The curves are a welcome difference from the square or boxy feeling of most entries in this challenge.', '2008-11-27 01:01:31.000000', NULL, 1),
(5086909, 740512, 89220, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2008-11-27 02:58:56.000000', NULL, 1),
(5086911, 741416, 89220, '<td valign="top">Oh God!!! Its gonna be with some ribbon.</td>', 'Oh God!!! Its gonna be with some ribbon.', '2008-11-27 02:59:31.000000', NULL, 1),
(5086913, 740751, 89220, '<td valign="top">Lovely.</td>', 'Lovely.', '2008-11-27 03:00:05.000000', NULL, 1),
(5086919, 741476, 89220, '<td valign="top">I love this.</td>', 'I love this.', '2008-11-27 03:03:02.000000', NULL, 1);
