(5089195, 741432, 18197, '<td valign="top">It''s actually a picnic table rather than a bench. Is that an airplane near the trees on the left?</td>', 'It''s actually a picnic table rather than a bench. Is that an airplane near the trees on the left?', '2008-11-28 20:47:10.000000', NULL, 1),
(5089198, 741483, 18197, '<td valign="top">Vignette and bright subject work well together.</td>', 'Vignette and bright subject work well together.', '2008-11-28 20:47:36.000000', NULL, 1),
(5089199, 741318, 18197, '<td valign="top">Good leading lines. Interesting choice of focus and DOF.</td>', 'Good leading lines. Interesting choice of focus and DOF.', '2008-11-28 20:48:06.000000', NULL, 1),
(5089202, 741336, 18197, '<td valign="top">Looks like a pleasant place to sit awhile ... in better weather of course.</td>', 'Looks like a pleasant place to sit awhile ... in better weather of course.', '2008-11-28 20:48:41.000000', NULL, 1),
(5089204, 741485, 18197, '<td valign="top">This didn''t appeal to me at first but i find myself coming back to it. It''s got nice intersecting lines which I like.</td>', 'This didn''t appeal to me at first but i find myself coming back to it. It''s got nice intersecting lines which I like.', '2008-11-28 20:49:30.000000', NULL, 1),
(5089206, 741397, 18197, '<td valign="top">Looks like a pleasant place to spend an afternoon.</td>', 'Looks like a pleasant place to spend an afternoon.', '2008-11-28 20:50:03.000000', NULL, 1),
(5089209, 741314, 18197, '<td valign="top">Among best of show. I like the sunburst mirror above the girl like a halo in a medieval painting which contrasts sharply with the fact that the girl doesn''t look much like a saint.</td>', 'Among best of show. I like the sunburst mirror above the girl like a halo in a medieval painting which contrasts sharply with the fact that the girl doesn''t look much like a saint.', '2008-11-28 20:52:10.000000', NULL, 1),
(5089214, 741426, 18197, '<td valign="top">Great photo. Brilliant perspective. Excellant color. There seem to be some sharpening artifacts either from tone mapping or from sharpening. I''d prefer less of these.</td>', 'Great photo. Brilliant perspective. Excellant color. There seem to be some sharpening artifacts either from tone mapping or from sharpening. I''d prefer less of these.', '2008-11-28 20:53:40.000000', NULL, 1),
(5089218, 741350, 18197, '<td valign="top">Superb photo. Love the subject, the composition, the leading lines, and even the post processing. Among best of show.</td>', 'Superb photo. Love the subject, the composition, the leading lines, and even the post processing. Among best of show.', '2008-11-28 20:54:34.000000', NULL, 1),
(5089221, 741332, 18197, '<td valign="top">Missing the bench.</td>', 'Missing the bench.', '2008-11-28 20:54:49.000000', NULL, 1),
(5089228, 740873, 18197, '<td valign="top">I like almost every thing about your photo. But the bench gets lost in the bush. If you had moved to your left a few feet, it would have been totally silhoutted against the sky and I might have liked it better.</td>', 'I like almost every thing about your photo. But the bench gets lost in the bush. If you had moved to your left a few feet, it would have been totally silhoutted against the sky and I might have liked it better.', '2008-11-28 20:56:33.000000', NULL, 1),
(5089230, 741282, 18197, '<td valign="top">Can you spell shoehorn? Doesn''t really meet the spirit of the challenge for me.</td>', 'Can you spell shoehorn? Doesn''t really meet the spirit of the challenge for me.', '2008-11-28 20:57:13.000000', NULL, 1),
(5089232, 741404, 18197, '<td valign="top">Really really good. I love the placement of the bench agains the city and the lines of the bridge. Compositionally superb.</td>', 'Really really good. I love the placement of the bench agains the city and the lines of the bridge. Compositionally superb.', '2008-11-28 20:58:06.000000', NULL, 1),
(5089234, 741501, 18197, '<td valign="top">I like the high contrast and the DOF. But the subject isn''t causing me to linger.</td>', 'I like the high contrast and the DOF. But the subject isn''t causing me to linger.', '2008-11-28 20:58:51.000000', NULL, 1),
(5089237, 741448, 18197, '<td valign="top">Terrific. The repeating pattern is strong. The straight benches agains the curved concrete makes for a dynamic feeling. Vignette works. Among best of show.</td>', 'Terrific. The repeating pattern is strong. The straight benches agains the curved concrete makes for a dynamic feeling. Vignette works. Among best of show.', '2008-11-28 21:00:13.000000', NULL, 1),
(5089242, 741039, 18197, '<td valign="top">I would prefer a more precise focus on something and straightening the horizon (but then I''m not entirely rational about tilt).</td>', 'I would prefer a more precise focus on something and straightening the horizon (but then I''m not entirely rational about tilt).', '2008-11-28 21:01:34.000000', NULL, 1),
(5089243, 741474, 18197, '<td valign="top">Extraordinary. I love the bits of snow, that the cat is the same color as the rest of the photo, the detail in the cat''s fur, the overall composition ... pretty much everything. Among best of show.</td>', 'Extraordinary. I love the bits of snow, that the cat is the same color as the rest of the photo, the detail in the cat''s fur, the overall composition ... pretty much everything. Among best of show.', '2008-11-28 21:03:09.000000', NULL, 1),
(5089246, 740987, 18197, '<td valign="top">Unusual perspective. Love the lines of the tree''s branches overhead.</td>', 'Unusual perspective. Love the lines of the tree''s branches overhead.', '2008-11-28 21:03:43.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5089247, 741083, 18197, '<td valign="top">Brilliant. The girl almost appears as artwork heerself. Among the best of show.</td>', 'Brilliant. The girl almost appears as artwork heerself. Among the best of show.', '2008-11-28 21:04:29.000000', NULL, 1),
(5089249, 740888, 18197, '<td valign="top">Good workmanlike photo but the subject isn''t holding my interest.</td>', 'Good workmanlike photo but the subject isn''t holding my interest.', '2008-11-28 21:05:04.000000', NULL, 1),
(5089251, 741436, 18197, '<td valign="top">Deceptively simple image masking strong composition, great colors and reflections and great clarity. This shows how taking good care of the fundamentals yields a strong photo.</td>', 'Deceptively simple image masking strong composition, great colors and reflections and great clarity. This shows how taking good care of the fundamentals yields a strong photo.', '2008-11-28 21:06:24.000000', NULL, 1),
(5089252, 741433, 18197, '<td valign="top">I like that it''s bright and optimistic.</td>', 'I like that it''s bright and optimistic.', '2008-11-28 21:06:52.000000', NULL, 1),
(5089254, 741271, 18197, '<td valign="top">Don''t like the title much but the rest of the photo seems to work. I like the whimsey of the pinwheel thingy juxtaposed with the dog''s expression.</td>', 'Don''t like the title much but the rest of the photo seems to work. I like the whimsey of the pinwheel thingy juxtaposed with the dog''s expression.', '2008-11-28 21:08:29.000000', NULL, 1),
(5089256, 741432, 33552, '<td valign="top">Already!!! Settle in and enjoy the beautiful white landscapes like this one. There will be quite a few more...</td>', 'Already!!! Settle in and enjoy the beautiful white landscapes like this one. There will be quite a few more...', '2008-11-28 21:12:49.000000', NULL, 1),
(5089259, 741483, 33552, '<td valign="top">Can''t really find anything wrong with this shot, but it doesn''t really create any emotional connection for <i>me</i>.</td>', 'Can''t really find anything wrong with this shot, but it doesn''t really create any emotional connection for me.', '2008-11-28 21:14:08.000000', NULL, 1),
(5089316, 741442, 63218, '<td valign="top">There are many beautiful views in the world &amp; many benches placed to rest &amp; enjoy them.  This is my pick for the best of the best of this category of bench. I like it for the tones &amp; the placement of detail. It feels familiar &amp; new at the same time. 10</td>', 'There are many beautiful views in the world & many benches placed to rest & enjoy them.  This is my pick for the best of the best of this category of bench. I like it for the tones & the placement of detail. It feels familiar & new at the same time. 10', '2008-11-28 22:04:42.000000', NULL, 1),
(5089353, 741474, 63218, '<td valign="top">This is my pick for Best in Show.  It was the little puffs of frozen snow on the ground that did it, combined with the interesting, uncompromising gaze of the Cat. The contrast is wonderful &amp; the colors are perfectly balanced. 10</td>', 'This is my pick for Best in Show.  It was the little puffs of frozen snow on the ground that did it, combined with the interesting, uncompromising gaze of the Cat. The contrast is wonderful & the colors are perfectly balanced. 10', '2008-11-28 22:48:13.000000', NULL, 1),
(5089359, 740639, 63218, '<td valign="top">This reminds me of turtles on a log (hehe).  The clipped shadows make the arrangment of people-parts seem as random &amp; unmoving as the cigarette butts.</td>', 'This reminds me of turtles on a log (hehe).  The clipped shadows make the arrangment of people-parts seem as random & unmoving as the cigarette butts.', '2008-11-28 22:55:03.000000', NULL, 1),
(5089392, 741454, 33552, '<td valign="top">A bit blue, I can''t say if it was intentional or not, but I don''t think it adds much here. A lower angle might help strengthen the composition.</td>', 'A bit blue, I can''t say if it was intentional or not, but I don''t think it adds much here. A lower angle might help strengthen the composition.', '2008-11-28 23:40:08.000000', NULL, 1),
(5089393, 741336, 33552, '<td valign="top">I''m sorry. I just don''t care for the processing. There is an overwhelming blue tint (HDR?) that if toned down might add a nice mood, but as is it''s just too much.</td>', 'I''m sorry. I just don''t care for the processing. There is an overwhelming blue tint (HDR?) that if toned down might add a nice mood, but as is it''s just too much.', '2008-11-28 23:40:24.000000', NULL, 1),
(5089394, 741412, 33552, '<td valign="top">There''s a blue cast over this one that detracts from what must be brilliant red leaves.</td>', 'There''s a blue cast over this one that detracts from what must be brilliant red leaves.', '2008-11-28 23:40:41.000000', NULL, 1),
(5089396, 741400, 33552, '<td valign="top">My first thought after reading the title was that the dog must be keeping the bench from falling over! Then I turned it over a few times and got what it was you were going for.</td>', 'My first thought after reading the title was that the dog must be keeping the bench from falling over! Then I turned it over a few times and got what it was you were going for.', '2008-11-28 23:42:30.000000', NULL, 1),
(5089457, 741423, 33552, '<td valign="top">Lots going on here. Nice comp.</td>', 'Lots going on here. Nice comp.', '2008-11-29 00:17:02.000000', NULL, 1),
(5089470, 741474, 33552, '<td valign="top">She''s cute, but I think she wants to attack!</td>', 'She''s cute, but I think she wants to attack!', '2008-11-29 00:21:10.000000', NULL, 1),
(5089484, 741307, 33552, '<td valign="top">Nice moment.</td>', 'Nice moment.', '2008-11-29 00:24:01.000000', NULL, 1),
(5089500, 740751, 33552, '<td valign="top">Beautiful scene. Minor nit.. I''d like to see the benches centered horizontally, they''re sooo close.</td>', 'Beautiful scene. Minor nit.. I''d like to see the benches centered horizontally, they''re sooo close.', '2008-11-29 00:26:57.000000', NULL, 1),
(5089505, 741416, 33552, '<td valign="top">Beautiful! Damn near perfect!</td>', 'Beautiful! Damn near perfect!', '2008-11-29 00:27:45.000000', NULL, 1),
(5089519, 740483, 33552, '<td valign="top">Nice detail.</td>', 'Nice detail.', '2008-11-29 00:33:08.000000', NULL, 1),
(5089525, 741376, 33552, '<td valign="top">Solid concept. Well executed.</td>', 'Solid concept. Well executed.', '2008-11-29 00:34:08.000000', NULL, 1),
(5089528, 741445, 33552, '<td valign="top">Try getting closer to strengthen the composition or back up a bit to add context.</td>', 'Try getting closer to strengthen the composition or back up a bit to add context.', '2008-11-29 00:35:12.000000', NULL, 1),
(5089531, 740841, 33552, '<td valign="top">Bold, interesting, excellent tonality.</td>', 'Bold, interesting, excellent tonality.', '2008-11-29 00:35:59.000000', NULL, 1),
(5089535, 741322, 33552, '<td valign="top">A bit busy. Try isolating the subject a bit more.</td>', 'A bit busy. Try isolating the subject a bit more.', '2008-11-29 00:37:06.000000', NULL, 1),
(5089544, 740784, 33552, '<td valign="top">Given the title, I''d like to see the pattern more prominantly featured, or perhaps echoed in the elsewhere in the frame.</td>', 'Given the title, I''d like to see the pattern more prominantly featured, or perhaps echoed in the elsewhere in the frame.', '2008-11-29 00:39:49.000000', NULL, 1),
(5089559, 741413, 33552, '<td valign="top">Processing seems a bit harsh. May just be a bit overexposed.</td>', 'Processing seems a bit harsh. May just be a bit overexposed.', '2008-11-29 00:46:02.000000', NULL, 1),
(5089567, 741491, 33552, '<td valign="top">The tilt is throwing me off big time here. Nice light.</td>', 'The tilt is throwing me off big time here. Nice light.', '2008-11-29 00:48:40.000000', NULL, 1),
(5089575, 741350, 33552, '<td valign="top">This damn scale doesn''t go up to 11!?!? Excellent mood, wonderful perspective, clear concept, and the couple in the BG ties this together beautifully.</td>', 'This damn scale doesn''t go up to 11!?!? Excellent mood, wonderful perspective, clear concept, and the couple in the BG ties this together beautifully.', '2008-11-29 00:50:58.000000', NULL, 1),
(5089583, 741006, 33552, '<td valign="top">Look on the bright side, it might just be an extra wing... <br/>Nice job catching the geese in flight, but that tall thing in the distance is really bugging me.</td>', 'Look on the bright side, it might just be an extra wing... Nice job catching the geese in flight, but that tall thing in the distance is really bugging me.', '2008-11-29 00:53:31.000000', NULL, 1),
(5089588, 741057, 33552, '<td valign="top">Ooooh.. I really love the colors and patterns here.</td>', 'Ooooh.. I really love the colors and patterns here.', '2008-11-29 00:54:48.000000', NULL, 1),
(5089599, 741073, 33552, '<td valign="top">A bit too much oblivion and not quite enough edge. Lovely pattern on the bricks. A horizontal, or even square, comp might show it off better with a bit less black space.</td>', 'A bit too much oblivion and not quite enough edge. Lovely pattern on the bricks. A horizontal, or even square, comp might show it off better with a bit less black space.', '2008-11-29 00:57:52.000000', NULL, 1),
(5089601, 740888, 33552, '<td valign="top">I''m at a loss for words...<br/>Um, where''s the bear?</td>', 'I''m at a loss for words...Um, where''s the bear?', '2008-11-29 00:59:35.000000', NULL, 1),
(5089607, 741369, 33552, '<td valign="top">Very pretty. A bit more mid tone contrast might help the eye to scan the entire image without getting sucked into the sun so quickly.</td>', 'Very pretty. A bit more mid tone contrast might help the eye to scan the entire image without getting sucked into the sun so quickly.', '2008-11-29 01:02:41.000000', NULL, 1),
(5089611, 741159, 33552, '<td valign="top">Very nice shot. The bench seems incidental, but the overall comp works.</td>', 'Very nice shot. The bench seems incidental, but the overall comp works.', '2008-11-29 01:03:56.000000', NULL, 1),
(5089618, 741431, 33552, '<td valign="top">Nice job stopping the gull''s motion, unfortunately it gets a little lost in the background.</td>', 'Nice job stopping the gull''s motion, unfortunately it gets a little lost in the background.', '2008-11-29 01:07:07.000000', NULL, 1),
(5089619, 741478, 33552, '<td valign="top">Looks like a nice spot. I''d love to see a square or horizontal shot here. It just seems a bit cut off on the right.</td>', 'Looks like a nice spot. I''d love to see a square or horizontal shot here. It just seems a bit cut off on the right.', '2008-11-29 01:08:33.000000', NULL, 1),
(5089622, 741501, 33552, '<td valign="top">Nice detail shot. Consider losing a bit off the top to balance this a bit.</td>', 'Nice detail shot. Consider losing a bit off the top to balance this a bit.', '2008-11-29 01:09:35.000000', NULL, 1),
(5089633, 741283, 33552, '<td valign="top">I can''t say that I care for the processing here, nor the tilted perspective, but the concept has promise. I prefer to see the attention naturally flow towards the subject. This just feels a bit forced.</td>', 'I can''t say that I care for the processing here, nor the tilted perspective, but the concept has promise. I prefer to see the attention naturally flow towards the subject. This just feels a bit forced.', '2008-11-29 01:16:04.000000', NULL, 1),
(5089636, 740615, 33552, '<td valign="top">Great emotion and composition, just ease up a bit on the processing and let the player''s emotion draw attention to itself. In sports, outside of advertising, we rarely see heavily processed images. In this case, just a little bit of editing can go a long way.</td>', 'Great emotion and composition, just ease up a bit on the processing and let the player''s emotion draw attention to itself. In sports, outside of advertising, we rarely see heavily processed images. In this case, just a little bit of editing can go a long way.', '2008-11-29 01:19:36.000000', NULL, 1),
(5089638, 741335, 33552, '<td valign="top">Nice detail and pattern.</td>', 'Nice detail and pattern.', '2008-11-29 01:20:36.000000', NULL, 1),
(5089640, 741442, 33552, '<td valign="top">Good job framing your subject with the tree. The sky here, however, is problematic. It''s so bright that my attention is drawn to it immediately.</td>', 'Good job framing your subject with the tree. The sky here, however, is problematic. It''s so bright that my attention is drawn to it immediately.', '2008-11-29 01:22:42.000000', NULL, 1),
(5089642, 741228, 33552, '<td valign="top">It''s so nice to see lens flare add to an image. Beautiful shapes, colors, and textures.</td>', 'It''s so nice to see lens flare add to an image. Beautiful shapes, colors, and textures.', '2008-11-29 01:24:16.000000', NULL, 1),
(5089646, 741365, 33552, '<td valign="top">Nice perspective. It might help to use the "rule of thirds" in a case like this. Place the horizon 1/3 from the top or bottom to strengthen the composition. Try it out by cropping this shot.</td>', 'Nice perspective. It might help to use the "rule of thirds" in a case like this. Place the horizon 1/3 from the top or bottom to strengthen the composition. Try it out by cropping this shot.', '2008-11-29 01:27:18.000000', NULL, 1),
(5089647, 741088, 33552, '<td valign="top">The reference is lost on me, but I do like the colors and the combination of various textures.</td>', 'The reference is lost on me, but I do like the colors and the combination of various textures.', '2008-11-29 01:29:38.000000', NULL, 1),
(5089650, 741014, 33552, '<td valign="top">The macabre scene and distorted perspective could create a dramatic shot, but the flat lighting betrays that initial impression.</td>', 'The macabre scene and distorted perspective could create a dramatic shot, but the flat lighting betrays that initial impression.', '2008-11-29 01:31:59.000000', NULL, 1),
(5089652, 740243, 33552, '<td valign="top">Decent composition and processing, but I''d like to be able to read something into the photo.</td>', 'Decent composition and processing, but I''d like to be able to read something into the photo.', '2008-11-29 01:33:59.000000', NULL, 1),
(5089654, 740473, 33552, '<td valign="top">I won''t give a full C&amp;C, as I can''t discern your intention, but the pose just doesn''t work for me here. The lighting/processing here presents a very dark, or at the very least dramatic, scenario.</td>', 'I won''t give a full C&C, as I can''t discern your intention, but the pose just doesn''t work for me here. The lighting/processing here presents a very dark, or at the very least dramatic, scenario.', '2008-11-29 01:37:08.000000', NULL, 1),
(5089655, 741490, 33552, '<td valign="top">Wow, that''s just so different. I''ve seen IR before, but this really does have an enchanted feel to it. Nice job.</td>', 'Wow, that''s just so different. I''ve seen IR before, but this really does have an enchanted feel to it. Nice job.', '2008-11-29 01:38:11.000000', NULL, 1),
(5089656, 741456, 33552, '<td valign="top">Very strong composition and creative use of flare.</td>', 'Very strong composition and creative use of flare.', '2008-11-29 01:39:41.000000', NULL, 1),
(5089658, 740782, 33552, '<td valign="top">Well executed concept. I''d just like to see it a bit less centered.</td>', 'Well executed concept. I''d just like to see it a bit less centered.', '2008-11-29 01:40:51.000000', NULL, 1),
(5089663, 740452, 33552, '<td valign="top">Overall, this is a very nice shot! It''s nit picking, I know, but, <i>for this challenge</i>, the bench is merely incidental. The photo on it''s own is worthy of a college catalog. **Market this Shot**</td>', 'Overall, this is a very nice shot! It''s nit picking, I know, but, for this challenge, the bench is merely incidental. The photo on it''s own is worthy of a college catalog. **Market this Shot**', '2008-11-29 01:43:59.000000', NULL, 1),
(5089664, 741429, 33552, '<td valign="top">Um, she looks like she''s ready to hurt someone...<br/>Very nice perspective and good use of high contrast.</td>', 'Um, she looks like she''s ready to hurt someone...Very nice perspective and good use of high contrast.', '2008-11-29 01:45:31.000000', NULL, 1),
(5089665, 741318, 33552, '<td valign="top">Very nice perspective, leading lines and timing. Top ten.</td>', 'Very nice perspective, leading lines and timing. Top ten.', '2008-11-29 01:46:19.000000', NULL, 1),
(5089667, 741248, 33552, '<td valign="top">There''s a bit of an issue where the steeple meets the sky, but the composition is strong.</td>', 'There''s a bit of an issue where the steeple meets the sky, but the composition is strong.', '2008-11-29 01:47:28.000000', NULL, 1),
(5089669, 741436, 33552, '<td valign="top">The bold colors and lighting save this from being anither lifeless bench. Good.</td>', 'The bold colors and lighting save this from being anither lifeless bench. Good.', '2008-11-29 01:48:37.000000', NULL, 1),
(5089671, 741282, 33552, '<td valign="top">With a lower perspective the rocks would have created a strong leading line to the subjects. As is, the bottom third, or even half, of this image contributes little. Try cropping in a bit closer.</td>', 'With a lower perspective the rocks would have created a strong leading line to the subjects. As is, the bottom third, or even half, of this image contributes little. Try cropping in a bit closer.', '2008-11-29 01:50:40.000000', NULL, 1),
(5089673, 741440, 33552, '<td valign="top">Nice concept. Try getting a bit closer and watch your horizon.</td>', 'Nice concept. Try getting a bit closer and watch your horizon.', '2008-11-29 01:51:21.000000', NULL, 1),
(5089677, 741271, 33552, '<td valign="top">Wow. That is strangely adorable. The top corners are a bit funky, but they can be easily cloned out if you choose. Very nicely done.</td>', 'Wow. That is strangely adorable. The top corners are a bit funky, but they can be easily cloned out if you choose. Very nicely done.', '2008-11-29 01:53:12.000000', NULL, 1),
(5089681, 741438, 33552, '<td valign="top">Almost pointilistic. Nice. Feels a bit tilted though (I know it''s hard to tell without a horizon).</td>', 'Almost pointilistic. Nice. Feels a bit tilted though (I know it''s hard to tell without a horizon).', '2008-11-29 01:55:10.000000', NULL, 1),
(5089683, 741277, 33552, '<td valign="top">It feels like I''m the one on the gurney. Creepy. The extreme tilt is <i>very</i> disorienting.</td>', 'It feels like I''m the one on the gurney. Creepy. The extreme tilt is very disorienting.', '2008-11-29 01:57:38.000000', NULL, 1),
(5089685, 740987, 33552, '<td valign="top">Nice perspective. Cool man vs. nature pattern conflict.</td>', 'Nice perspective. Cool man vs. nature pattern conflict.', '2008-11-29 01:58:27.000000', NULL, 1),
(5089687, 741290, 33552, '<td valign="top">Wow. Yes. The title says it all. Wow.</td>', 'Wow. Yes. The title says it all. Wow.', '2008-11-29 01:59:50.000000', NULL, 1),
(5089691, 741309, 33552, '<td valign="top">They are so cute... even when they are trying to attack you!</td>', 'They are so cute... even when they are trying to attack you!', '2008-11-29 02:02:46.000000', NULL, 1),
(5089694, 741417, 33552, '<td valign="top">Maybe a bit too hidden? Interesting concept with the super-high saturation.</td>', 'Maybe a bit too hidden? Interesting concept with the super-high saturation.', '2008-11-29 02:03:53.000000', NULL, 1),
(5089695, 740557, 33552, '<td valign="top">Beautiful sky. Long exposure? I like the perspective too.</td>', 'Beautiful sky. Long exposure? I like the perspective too.', '2008-11-29 02:04:49.000000', NULL, 1),
(5089699, 741404, 33552, '<td valign="top">Very nice! Damn near perfect execution of a classic concept.</td>', 'Very nice! Damn near perfect execution of a classic concept.', '2008-11-29 02:05:37.000000', NULL, 1),
(5089701, 740639, 33552, '<td valign="top">Nice. The exposure is a bit rough, but the concept comes across nicely. Well done.</td>', 'Nice. The exposure is a bit rough, but the concept comes across nicely. Well done.', '2008-11-29 02:07:12.000000', NULL, 1),
(5089708, 741397, 33552, '<td valign="top">Cool scene, but I think you''re trying to fit too much in. In case you can get back to this spot, I can see an awesome shot using a 200-300mm lens to compress the perspective, keeping the bench in the foreground and the building in the BG while limiting the scope of the distant BG.</td>', 'Cool scene, but I think you''re trying to fit too much in. In case you can get back to this spot, I can see an awesome shot using a 200-300mm lens to compress the perspective, keeping the bench in the foreground and the building in the BG while limiting the scope of the distant BG.', '2008-11-29 02:10:52.000000', NULL, 1),
(5089709, 741089, 33552, '<td valign="top">Try to add a bit more context or a different perspective to strengthen this shot.</td>', 'Try to add a bit more context or a different perspective to strengthen this shot.', '2008-11-29 02:11:57.000000', NULL, 1),
(5089712, 741011, 33552, '<td valign="top">Nice perspective, but try easing up on the processing. The grass is getting all funky...</td>', 'Nice perspective, but try easing up on the processing. The grass is getting all funky...', '2008-11-29 02:13:03.000000', NULL, 1),
(5089741, 741376, 96915, '<td valign="top">Stunning. A favorite.</td>', 'Stunning. A favorite.', '2008-11-29 02:52:12.000000', NULL, 1),
(5089917, 741050, 65234, '<td valign="top">Lovely fiery colors in the sky and interesting composition.  I see one lonely little duck in the pond ... oops, found another one.  They can swim off into the sunset together while romantic music swells in the background ;-)</td>', 'Lovely fiery colors in the sky and interesting composition.  I see one lonely little duck in the pond ... oops, found another one.  They can swim off into the sunset together while romantic music swells in the background ;-)', '2008-11-29 08:44:15.000000', NULL, 1),
(5089919, 741350, 65234, '<td valign="top">Very despairing body language and interesting curves to follow to the background.  Light was either very uneven or you dodged a bit extra in some spots.</td>', 'Very despairing body language and interesting curves to follow to the background.  Light was either very uneven or you dodged a bit extra in some spots.', '2008-11-29 08:46:23.000000', NULL, 1),
(5089921, 741442, 65234, '<td valign="top">I like the tree (Weeping Willow, maybe) shading the bench; it makes me imagine spring.  If possible I might have moved a step or two left to get the big house out of the background.</td>', 'I like the tree (Weeping Willow, maybe) shading the bench; it makes me imagine spring.  If possible I might have moved a step or two left to get the big house out of the background.', '2008-11-29 08:48:31.000000', NULL, 1),
(5089924, 741309, 65234, '<td valign="top">Adorable pose and great title :-)  The little feller is nicely framed by the bench and it was very cooperative of him to pose in a patch of light.  This one makes me smile.</td>', 'Adorable pose and great title :-)  The little feller is nicely framed by the bench and it was very cooperative of him to pose in a patch of light.  This one makes me smile.', '2008-11-29 08:50:44.000000', NULL, 1),
(5089929, 741453, 65234, '<td valign="top">Including bird poo, I see.  I like this, though.  It''s very simple but reminds me of so many well-used and well-worn benches in leafy city parks, and the stories they could tell.</td>', 'Including bird poo, I see.  I like this, though.  It''s very simple but reminds me of so many well-used and well-worn benches in leafy city parks, and the stories they could tell.', '2008-11-29 08:52:41.000000', NULL, 1),
(5089930, 740977, 65234, '<td valign="top">Perfect angle to get all those shapes inside one another, like a mirror facing a mirror.</td>', 'Perfect angle to get all those shapes inside one another, like a mirror facing a mirror.', '2008-11-29 08:52:52.000000', NULL, 1),
(5089933, 741456, 65234, '<td valign="top">Unusual use of light but really fun to see the beams this way.  I like the angle so the non-benches in the background are not prominent or distracting; I imagine the view is dramatically different if you stand up.  And while ordinarily I would think blowing out the sky was a bad thing, in this case it works for me.  I see a little banding where the sky meets the bench on top and on the left that feels to me like it should be blurred or cloned to remove the harshness.</td>', 'Unusual use of light but really fun to see the beams this way.  I like the angle so the non-benches in the background are not prominent or distracting; I imagine the view is dramatically different if you stand up.  And while ordinarily I would think blowing out the sky was a bad thing, in this case it works for me.  I see a little banding where the sky meets the bench on top and on the left that feels to me like it should be blurred or cloned to remove the harshness.', '2008-11-29 08:59:24.000000', NULL, 1),
(5089934, 741006, 65234, '<td valign="top">I see a wing!  Reminds me of one of those comedy sketches where people and props keep appearing briefly over the top of a couch, only hinting at what is going on that we can''t see.</td>', 'I see a wing!  Reminds me of one of those comedy sketches where people and props keep appearing briefly over the top of a couch, only hinting at what is going on that we can''t see.', '2008-11-29 09:03:33.000000', NULL, 1),
(5089936, 741417, 65234, '<td valign="top">Very pretty place.  I like the light filtering through the trees and the autumn colors.</td>', 'Very pretty place.  I like the light filtering through the trees and the autumn colors.', '2008-11-29 09:04:31.000000', NULL, 1),
(5089938, 741318, 65234, '<td valign="top">I like this.  I like it even better cropped tighter on top so the fence on the left runs out of the picture instead of ending by pointing at the buildings beyond.</td>', 'I like this.  I like it even better cropped tighter on top so the fence on the left runs out of the picture instead of ending by pointing at the buildings beyond.', '2008-11-29 09:04:37.000000', NULL, 1),
(5089945, 740782, 65234, '<td valign="top">The single dry leaf looks quite forlorn on the bench.  Very nice bokeh in the background.  A simple shot but eloquent.</td>', 'The single dry leaf looks quite forlorn on the bench.  Very nice bokeh in the background.  A simple shot but eloquent.', '2008-11-29 09:09:16.000000', NULL, 1),
(5089947, 741341, 65234, '<td valign="top">Certainly lokos like a very intriguing place to be.</td>', 'Certainly lokos like a very intriguing place to be.', '2008-11-29 09:09:52.000000', NULL, 1),
(5089956, 740557, 65234, '<td valign="top">Lovely sky and I rather like the slight distortion in the bench.  I do wish there wasn''t a sign or whatever that is next to it, so if possible (I know it isn''t always) I might have tried a few different angles to see if I could eliminate it from the scene, leaving the bench alone to witness the faraway city.</td>', 'Lovely sky and I rather like the slight distortion in the bench.  I do wish there wasn''t a sign or whatever that is next to it, so if possible (I know it isn''t always) I might have tried a few different angles to see if I could eliminate it from the scene, leaving the bench alone to witness the faraway city.', '2008-11-29 09:12:58.000000', NULL, 1),
(5089959, 741404, 65234, '<td valign="top">Very nicely composed; the tree''s hiding whatever was in the middle ground there, and the arch of the bridge frames the bench and visibly connects the peaceful bench to the cluttered city beyond.</td>', 'Very nicely composed; the tree''s hiding whatever was in the middle ground there, and the arch of the bridge frames the bench and visibly connects the peaceful bench to the cluttered city beyond.', '2008-11-29 09:15:15.000000', NULL, 1),
(5089964, 741317, 65234, '<td valign="top">Looks cold and windy as well as lonely.  Difficult exposure with that much of the sun breaking through the clouds; I''d try to capture it when the sun was more obscured if I could.</td>', 'Looks cold and windy as well as lonely.  Difficult exposure with that much of the sun breaking through the clouds; I''d try to capture it when the sun was more obscured if I could.', '2008-11-29 09:19:10.000000', NULL, 1),
(5089969, 741285, 65234, '<td valign="top">That cheery little butterfly mug looks really out of place.  For this challenge I''d like the bench to be more important to the image; he could be sitting on a rock wall and the effect would be the same.</td>', 'That cheery little butterfly mug looks really out of place.  For this challenge I''d like the bench to be more important to the image; he could be sitting on a rock wall and the effect would be the same.', '2008-11-29 09:24:16.000000', NULL, 1),
(5089970, 741159, 65234, '<td valign="top">Nice lines to the composition.</td>', 'Nice lines to the composition.', '2008-11-29 09:24:39.000000', NULL, 1),
(5089971, 741448, 65234, '<td valign="top">Lines made by the benches are kind of cool, but I wonder if a different angle might make for a more interesting shot, maybe with more convergence of the lines or some detail on a foreground bench and the lines slowly fading out of focus.</td>', 'Lines made by the benches are kind of cool, but I wonder if a different angle might make for a more interesting shot, maybe with more convergence of the lines or some detail on a foreground bench and the lines slowly fading out of focus.', '2008-11-29 09:27:45.000000', NULL, 1),
(5089982, 741489, 65234, '<td valign="top">The exposure works well to draw my eye but then I jump to the hanging thingy and the light in the arches, which is yellow on one side and peachy on the other and has areas of sharp focus.  I think I would like this much better in straight black and white and either cropped tighter on top or with a different DOF so the arches weren''t competing for my attention.</td>', 'The exposure works well to draw my eye but then I jump to the hanging thingy and the light in the arches, which is yellow on one side and peachy on the other and has areas of sharp focus.  I think I would like this much better in straight black and white and either cropped tighter on top or with a different DOF so the arches weren''t competing for my attention.', '2008-11-29 09:33:21.000000', NULL, 1),
(5089987, 741474, 65234, '<td valign="top">Good thing she''s wearing a heavy coat.  She looks a little ... imperious, I think.  I like the composition although I think I like it a little better with the bottom cropped tighter.  You lose the snow but I like the spot where that cat ends up that way.</td>', 'Good thing she''s wearing a heavy coat.  She looks a little ... imperious, I think.  I like the composition although I think I like it a little better with the bottom cropped tighter.  You lose the snow but I like the spot where that cat ends up that way.', '2008-11-29 09:35:15.000000', NULL, 1),
