(5090475, 741318, 75328, '<td valign="top">no doubt one of the bests. perfect and beautiful.</td>', 'no doubt one of the bests. perfect and beautiful.', '2008-11-29 16:45:35.000000', NULL, 1),
(5090546, 740615, 96915, '<td valign="top">I''m quite surprised that this is the only sport-related bench in this challenge.  The idea of being benched was the first thing to come to my mind when this challenge was announced, though I didn''t enter.  I think you''ve captured the idea of "losing" very well here with the cheerleaders standing in the background, but I''m less fond of the processing.  I don''t mind the selective de-saturation as much as I usually do (perhaps because it''s subtle, but I''m not fond of the diffuse glow or whatever is giving that effect.</td>', 'I''m quite surprised that this is the only sport-related bench in this challenge.  The idea of being benched was the first thing to come to my mind when this challenge was announced, though I didn''t enter.  I think you''ve captured the idea of "losing" very well here with the cheerleaders standing in the background, but I''m less fond of the processing.  I don''t mind the selective de-saturation as much as I usually do (perhaps because it''s subtle, but I''m not fond of the diffuse glow or whatever is giving that effect.', '2008-11-29 18:21:42.000000', NULL, 1),
(5090548, 741425, 96915, '<td valign="top">Interesting subject, but the photograph itself leaves something to be desired.  Perhaps try shooting this at a different time of day when the lighting is not so harsh, or change the angle, as this appears a bit like a snapshot taken from the standard standing position.</td>', 'Interesting subject, but the photograph itself leaves something to be desired.  Perhaps try shooting this at a different time of day when the lighting is not so harsh, or change the angle, as this appears a bit like a snapshot taken from the standard standing position.', '2008-11-29 18:23:48.000000', NULL, 1),
(5090551, 741159, 96915, '<td valign="top">Very nice lines.  I think the foreground could stand to be cropped a bit, to just near where the step meets the edge of the frame.</td>', 'Very nice lines.  I think the foreground could stand to be cropped a bit, to just near where the step meets the edge of the frame.', '2008-11-29 18:25:22.000000', NULL, 1),
(5090554, 741259, 96915, '<td valign="top">I strongly dislike the processing in this.  Sorry :(</td>', 'I strongly dislike the processing in this.  Sorry :(', '2008-11-29 18:26:23.000000', NULL, 1),
