(5091476, 741334, 52549, '<td valign="top">Well seen! Like the b/w toning.</td>', 'Well seen! Like the b/w toning.', '2008-11-30 14:11:49.000000', NULL, 1),
(5091477, 740784, 52549, '<td valign="top">Lovely image. The wooden slats have a wonderful curve.</td>', 'Lovely image. The wooden slats have a wonderful curve.', '2008-11-30 14:12:49.000000', NULL, 1),
(5091479, 741490, 52549, '<td valign="top">Title suits it perfectly, it does indeed look enchanted. Lovely IR.</td>', 'Title suits it perfectly, it does indeed look enchanted. Lovely IR.', '2008-11-30 14:13:21.000000', NULL, 1),
(5091480, 740557, 52549, '<td valign="top">I wonder if this bench is in Iceland ;-) Fabulous image, must be top three.</td>', 'I wonder if this bench is in Iceland ;-) Fabulous image, must be top three.', '2008-11-30 14:14:09.000000', NULL, 1),
(5091481, 741376, 52549, '<td valign="top">This is so beautiful however I think it looks more like "solace" than grief. No matter, it''s a wonderful image.</td>', 'This is so beautiful however I think it looks more like "solace" than grief. No matter, it''s a wonderful image.', '2008-11-30 14:15:39.000000', NULL, 1),
(5091483, 741218, 52549, '<td valign="top">Love the yellow/gold tones. Very interesting image.</td>', 'Love the yellow/gold tones. Very interesting image.', '2008-11-30 14:16:23.000000', NULL, 1),
(5091484, 741416, 52549, '<td valign="top">Love it, great shot.</td>', 'Love it, great shot.', '2008-11-30 14:18:07.000000', NULL, 1),
(5091542, 741376, 91614, '<td valign="top">Wow I love the grey tones. The image really supports the title. Amazing job.</td>', 'Wow I love the grey tones. The image really supports the title. Amazing job.', '2008-11-30 15:11:28.000000', NULL, 1),
(5091543, 741050, 91614, '<td valign="top">This is just gorgeous. I hope it ribbons. The sunset really makes it. Good job! :)</td>', 'This is just gorgeous. I hope it ribbons. The sunset really makes it. Good job! :)', '2008-11-30 15:12:39.000000', NULL, 1),
(5091544, 741476, 91614, '<td valign="top">Wow. This is fantastic. I love the white and the border is really nice.</td>', 'Wow. This is fantastic. I love the white and the border is really nice.', '2008-11-30 15:13:44.000000', NULL, 1),
(5091547, 740841, 91614, '<td valign="top">Very cool perspective. I love the sky gradient.</td>', 'Very cool perspective. I love the sky gradient.', '2008-11-30 15:14:46.000000', NULL, 1),
(5091549, 741416, 91614, '<td valign="top">Wow. Love the purple/blue tones. Very striking. The silhouette is very nice.</td>', 'Wow. Love the purple/blue tones. Very striking. The silhouette is very nice.', '2008-11-30 15:15:44.000000', NULL, 1),
(5091552, 740557, 91614, '<td valign="top">Wow. Really pretty sky.</td>', 'Wow. Really pretty sky.', '2008-11-30 15:16:37.000000', NULL, 1),
(5091559, 741083, 91614, '<td valign="top">The lighting is so striking in this photo. It creates wonderful soft shadows. I love the composition too. Amazing work. :)</td>', 'The lighting is so striking in this photo. It creates wonderful soft shadows. I love the composition too. Amazing work. :)', '2008-11-30 15:18:45.000000', NULL, 1),
(5091567, 741369, 91614, '<td valign="top">Wow. this is really peaceful and serene. Great work! :)</td>', 'Wow. this is really peaceful and serene. Great work! :)', '2008-11-30 15:21:22.000000', NULL, 1),
(5091568, 741337, 91614, '<td valign="top">Ah. I love black and white photographs. This one has amazing contrast.</td>', 'Ah. I love black and white photographs. This one has amazing contrast.', '2008-11-30 15:21:47.000000', NULL, 1),
(5091649, 741487, 90414, '<td valign="top">Ah, very romantic scene. Burning the (relatively unimportant)patio pavers and left side of the shot would have kept my eyes on the model and flowers better.</td>', 'Ah, very romantic scene. Burning the (relatively unimportant)patio pavers and left side of the shot would have kept my eyes on the model and flowers better.', '2008-11-30 16:40:15.000000', NULL, 1),
(5091673, 741404, 98647, '<td valign="top">Good foreground interest with the tree and background interest with the buildings</td>', 'Good foreground interest with the tree and background interest with the buildings', '2008-11-30 16:56:01.000000', NULL, 1),
(5091675, 741006, 98647, '<td valign="top">The image is a little bright, or maybe that was your intention.</td>', 'The image is a little bright, or maybe that was your intention.', '2008-11-30 16:58:55.000000', NULL, 1),
(5091676, 740512, 98647, '<td valign="top">The colours are a bit odd to me. Oversaturated?</td>', 'The colours are a bit odd to me. Oversaturated?', '2008-11-30 17:01:51.000000', NULL, 1),
(5091678, 741498, 90414, '<td valign="top">Nice shot with natural tones, but I wonder what a b/w or sepia version would look like?</td>', 'Nice shot with natural tones, but I wonder what a b/w or sepia version would look like?', '2008-11-30 17:03:35.000000', NULL, 1),
(5091679, 741369, 98647, '<td valign="top">I like the mood in this picture, but I find the sun to be too bright. It''s the first thing your eye goes to.</td>', 'I like the mood in this picture, but I find the sun to be too bright. It''s the first thing your eye goes to.', '2008-11-30 17:04:09.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5091681, 741376, 75328, '<td valign="top">yes! <br/> <br/>reminds me of six feet under...</td>', 'yes!  reminds me of six feet under...', '2008-11-30 17:05:48.000000', NULL, 1),
(5091685, 741218, 90414, '<td valign="top">Wonderful composition, interesting contrapuntal lighting.</td>', 'Wonderful composition, interesting contrapuntal lighting.', '2008-11-30 17:08:32.000000', NULL, 1),
(5091688, 741033, 90414, '<td valign="top">Lovely church, but a bit bright for my taste... burning the arches and columns slightly would have added more mood imo.</td>', 'Lovely church, but a bit bright for my taste... burning the arches and columns slightly would have added more mood imo.', '2008-11-30 17:10:05.000000', NULL, 1),
(5091692, 741487, 98647, '<td valign="top">Compared to the warm colours in the background, the foreground lighting is harsh.</td>', 'Compared to the warm colours in the background, the foreground lighting is harsh.', '2008-11-30 17:13:13.000000', NULL, 1),
(5091696, 740512, 90414, '<td valign="top">Great colors and composition. No negatives here...</td>', 'Great colors and composition. No negatives here...', '2008-11-30 17:15:40.000000', NULL, 1),
(5091697, 741430, 98647, '<td valign="top">A little too much going on. Maybe if you had shot from a different angle you could have eliminated some of the surrounding elements and made the bench more the focus of the photo.</td>', 'A little too much going on. Maybe if you had shot from a different angle you could have eliminated some of the surrounding elements and made the bench more the focus of the photo.', '2008-11-30 17:17:43.000000', NULL, 1),
(5091698, 741389, 98647, '<td valign="top">Good composition</td>', 'Good composition', '2008-11-30 17:18:43.000000', NULL, 1),
(5091699, 741259, 90414, '<td valign="top">Using a filter to make a shot more interesting doesn''t necessarily make up for a blah composition. (Check out my Where is Art Roflmao shot for proof.)</td>', 'Using a filter to make a shot more interesting doesn''t necessarily make up for a blah composition. (Check out my Where is Art Roflmao shot for proof.)', '2008-11-30 17:19:19.000000', NULL, 1),
(5091700, 740782, 90414, '<td valign="top">I really like the monotone treatment and dof in this shot... well done.</td>', 'I really like the monotone treatment and dof in this shot... well done.', '2008-11-30 17:20:11.000000', NULL, 1),
(5091704, 741350, 90414, '<td valign="top">Great lines and tones, as well as very emotive shot.</td>', 'Great lines and tones, as well as very emotive shot.', '2008-11-30 17:22:42.000000', NULL, 1),
(5091705, 741073, 98647, '<td valign="top">I like the way the light ''fans'' out on the pavement. The man is a little dark, but I guess you were using what light was available. I would crop some off either the top or bottom.</td>', 'I like the way the light ''fans'' out on the pavement. The man is a little dark, but I guess you were using what light was available. I would crop some off either the top or bottom.', '2008-11-30 17:23:41.000000', NULL, 1),
(5091709, 741444, 98647, '<td valign="top">When I look at your photo I think serenity, peace. The moving person walking out of the frame doesn''t quite add to that. Beautiful image though.</td>', 'When I look at your photo I think serenity, peace. The moving person walking out of the frame doesn''t quite add to that. Beautiful image though.', '2008-11-30 17:28:00.000000', NULL, 1),
(5091715, 740079, 90414, '<td valign="top">I didn''t know the fates were senior citizens! Interesting shot.</td>', 'I didn''t know the fates were senior citizens! Interesting shot.', '2008-11-30 17:33:26.000000', NULL, 1),
(5091718, 741154, 98647, '<td valign="top">Beautiful colours</td>', 'Beautiful colours', '2008-11-30 17:35:47.000000', NULL, 1),
(5091732, 741335, 90414, '<td valign="top">Unusual take on the church shot (vs. right down the center aisle.) Lovely lighting, but for the blown out window light.</td>', 'Unusual take on the church shot (vs. right down the center aisle.) Lovely lighting, but for the blown out window light.', '2008-11-30 17:53:57.000000', NULL, 1),
(5091737, 741436, 90414, '<td valign="top">The glare on the bench detracts slightly for me, but the black/red contrast works well.</td>', 'The glare on the bench detracts slightly for me, but the black/red contrast works well.', '2008-11-30 17:57:41.000000', NULL, 1),
(5091744, 741014, 90414, '<td valign="top">Quite a maudlin verse and photo. The bush competes with the bench too much.</td>', 'Quite a maudlin verse and photo. The bush competes with the bench too much.', '2008-11-30 18:01:38.000000', NULL, 1),
(5091748, 741161, 90414, '<td valign="top">The very bottom of the frame is too bright imo. This could have been cropped out or burned to keep attention on dog and owner. Nice portrait though.</td>', 'The very bottom of the frame is too bright imo. This could have been cropped out or burned to keep attention on dog and owner. Nice portrait though.', '2008-11-30 18:04:55.000000', NULL, 1),
(5091754, 741336, 90414, '<td valign="top">Nice composition overall with even tones and colors. BUT, to me these are Adirondack type chairs and not benches.</td>', 'Nice composition overall with even tones and colors. BUT, to me these are Adirondack type chairs and not benches.', '2008-11-30 18:09:39.000000', NULL, 1),
(5091755, 741356, 90414, '<td valign="top">Nice idea, but overall it is too washed out for me.</td>', 'Nice idea, but overall it is too washed out for me.', '2008-11-30 18:12:12.000000', NULL, 1),
(5091757, 741423, 90414, '<td valign="top">Interesting lines and a well conceived / executed composition for me.</td>', 'Interesting lines and a well conceived / executed composition for me.', '2008-11-30 18:14:39.000000', NULL, 1),
(5091760, 741322, 90414, '<td valign="top">Nice framing of the bench, but something just doesn''t keep my interest... too much sky perhaps, or the stone wall on the left competes too much.</td>', 'Nice framing of the bench, but something just doesn''t keep my interest... too much sky perhaps, or the stone wall on the left competes too much.', '2008-11-30 18:18:20.000000', NULL, 1),
(5091761, 741501, 90414, '<td valign="top">Excellent minimalist composition w/ nice dof.</td>', 'Excellent minimalist composition w/ nice dof.', '2008-11-30 18:19:09.000000', NULL, 1),
(5091765, 740841, 90414, '<td valign="top">Great POV. One of my faves in the challenge.</td>', 'Great POV. One of my faves in the challenge.', '2008-11-30 18:23:06.000000', NULL, 1),
(5091768, 741228, 90414, '<td valign="top">I like the composition, but the "rays" look much like an effect to me, and a bit unnatural.</td>', 'I like the composition, but the "rays" look much like an effect to me, and a bit unnatural.', '2008-11-30 18:26:29.000000', NULL, 1),
(5091782, 741434, 90414, '<td valign="top">Very snapshot-ish imo. Maybe a different perspective (backlit in silhouette for instance) with less dead space would have made a stronger shot.</td>', 'Very snapshot-ish imo. Maybe a different perspective (backlit in silhouette for instance) with less dead space would have made a stronger shot.', '2008-11-30 18:41:05.000000', NULL, 1),
(5091786, 741318, 90414, '<td valign="top">Strong composition, quite metaphorical - the literal "end of the line" is where we all end up after all.</td>', 'Strong composition, quite metaphorical - the literal "end of the line" is where we all end up after all.', '2008-11-30 18:43:10.000000', NULL, 1),
(5091790, 740873, 90414, '<td valign="top">The bench blends in with the vegetation imo. Re-composing from your left would have shown it better against the water.</td>', 'The bench blends in with the vegetation imo. Re-composing from your left would have shown it better against the water.', '2008-11-30 18:54:52.000000', NULL, 1),
(5091791, 741417, 86974, '<td valign="top">This is a nice colorful shot but the bench is to hidden for my taste.</td>', 'This is a nice colorful shot but the bench is to hidden for my taste.', '2008-11-30 18:55:13.000000', NULL, 1),
(5091802, 741309, 90414, '<td valign="top">Extra points for the furry component!</td>', 'Extra points for the furry component!', '2008-11-30 19:05:16.000000', NULL, 1),
